{
  "status": "Ready",
  "current_position": {
    "confirmed": [
      {
        "id": "CP-001",
        "statement": "Dataverse remains the system of record for case data.",
        "basis": "Settled ownership decision supplied in the continuation brief.",
        "source_refs": [
          "User continuation brief"
        ]
      },
      {
        "id": "CP-002",
        "statement": "The model-driven app owns operator entry and feedback.",
        "basis": "Settled experience decision supplied in the continuation brief.",
        "source_refs": [
          "User continuation brief"
        ]
      },
      {
        "id": "CP-003",
        "statement": "The existing server-side handler exclusively owns governed status transitions.",
        "basis": "Settled lifecycle ownership decision supplied in the continuation brief.",
        "source_refs": [
          "User continuation brief"
        ]
      },
      {
        "id": "CP-004",
        "statement": "Direct client writes to governed status are rejected and remain out of scope.",
        "basis": "Settled security and integrity decision supplied in the continuation brief.",
        "source_refs": [
          "User continuation brief"
        ]
      },
      {
        "id": "CP-005",
        "statement": "The prior slice proved its local form and handler tests only.",
        "basis": "Evidence boundary explicitly supplied by the user; no package, deployment, or target-runtime proof was supplied.",
        "source_refs": [
          "User continuation brief"
        ]
      }
    ],
    "assumptions": [
      {
        "id": "AS-001",
        "statement": "The solution can add one required resolution-reason attribute to the existing case table and expose it on the existing operator form.",
        "impact": "The exact publisher-prefixed schema name, label, text length, and form placement can follow repository conventions without changing ownership.",
        "validation_required": "Resolve these values from current solution conventions before implementation and verify them in the exported package.",
        "source_refs": [
          "Synthetic continuation scope"
        ]
      },
      {
        "id": "AS-002",
        "statement": "The existing close request can be extended to carry a resolution reason, correlation ID, concurrency token, and duplicate-action identifier.",
        "impact": "No new transition owner or parallel write path is required.",
        "validation_required": "Confirm the existing handler contract and duplicate-protection convention during source inspection before editing.",
        "source_refs": [
          "Settled server-side ownership",
          "Synthetic bounded assumption"
        ]
      },
      {
        "id": "AS-003",
        "statement": "Resolution reason content may be stored in Dataverse but must not be emitted in telemetry.",
        "impact": "Telemetry remains privacy-safe while preserving operational diagnostics.",
        "validation_required": "Confirm organisational classification, retention, and telemetry-destination configuration before deployment.",
        "source_refs": [
          "Synthetic data boundary"
        ]
      }
    ],
    "open_questions": [
      {
        "id": "OQ-001",
        "question": "What publisher-prefixed schema name, maximum length, form location, and telemetry destination should be used?",
        "owner": "Authorised implementation and deployment owners",
        "blocks_ready": false
      }
    ],
    "rejected": [
      {
        "id": "RJ-001",
        "decision": "Allow the model-driven client to write governed status directly.",
        "reason": "It would bypass the established server-side transition owner and weaken validation, concurrency, telemetry, and duplicate protection.",
        "reconsider_if": "Only if new authoritative architecture and security evidence formally replaces the settled transition owner."
      },
      {
        "id": "RJ-002",
        "decision": "Introduce a second workflow, handler, or direct-write path for closing cases.",
        "reason": "It would create competing lifecycle owners and a duplicate-processing risk.",
        "reconsider_if": "Only if the existing owner is formally retired with migration and replay evidence."
      }
    ],
    "superseded": []
  },
  "boundary": {
    "zone": "personal-openai",
    "data_classification": "synthetic",
    "cross_zone_transfer": "permitted"
  },
  "slice": {
    "outcome": "An authorised operator can enter a resolution reason and request closure from the model-driven case form; the existing server-side owner validates and atomically persists the reason with the close transition, while the operator receives deterministic success or failure feedback and privacy-safe telemetry supports target verification.",
    "entry": "An authorised case operator opens an existing eligible case in the model-driven app. The close command is enabled only when the record is loaded, editable, not already closed, and no close request is in flight. Activating it presents or focuses the operator-visible resolution-reason input and initiates the existing close path.",
    "validation": "The client provides immediate required-field and length feedback but does not decide transition eligibility. Before any durable change, the existing server-side handler verifies caller permission, current case state, a nonblank normalized resolution reason within the configured limit, the current concurrency token, and duplicate-action protection. Invalid, forbidden, stale, already-processed, or ineligible requests must produce typed failures without changing status or overwriting either version.",
    "persistence_or_action": "Extend the existing close contract and handler only. The handler uses a per-attempt correlation ID and idempotency key or equivalent duplicate-action guard, then persists the normalized resolution reason and performs the governed close transition as one authoritative transactional operation. The client never writes governed status directly.",
    "feedback": "While closure is pending, disable repeated submission and expose an accessible busy state. Show inline validation with focus moved to the resolution-reason input. On success, refresh the authoritative Dataverse record and announce that the case closed. Map permission and ineligible-state failures to non-retry guidance; map concurrency conflicts to reload-and-reconcile guidance; map transient failures to a safe retry action using duplicate protection. Preserve the entered reason after failures, support keyboard and screen-reader use, and safely render narrow and long-content states.",
    "telemetry": "Emit privacy-safe close-requested, close-succeeded, and close-failed events from the authoritative path with correlation ID, operation name, duration, outcome category, case-state category, and conflict or duplicate signal. Do not emit the resolution reason, case title, user-entered text, personal identifiers, record payloads, tokens, or credentials. Correlate client feedback to the server outcome without creating a second lifecycle owner.",
    "evidence": "Local proof must cover focused form and handler tests, including validation, permission, concurrency, duplicate submission, atomic persistence, feedback mapping, accessibility, and telemetry redaction. Package proof must show the attribute, form, command dependencies, handler changes, and telemetry configuration are present. Deployment proof must include successful import, dependency and configuration readback, security-role verification, and handler registration readback. Target runtime proof must demonstrate successful closure and persisted reason, required-field rejection, permission rejection, stale conflict without data loss, transient failure and safe retry, duplicate replay without a second transition, telemetry correlation and redaction, and confirmation that direct governed-status writes remain rejected.",
    "scope": [
      "Add one operator-visible resolution-reason attribute to the existing case data model and form.",
      "Extend the existing close request and existing server-side handler to validate and persist the reason.",
      "Keep the reason write and governed close transition under the existing authoritative owner.",
      "Add deterministic loading, validation, permission, conflict, retry, failure, and success feedback.",
      "Add privacy-safe correlated telemetry for request, success, failure, conflict, and duplicate outcomes.",
      "Add focused automated, package, deployment, runtime, accessibility, security, reliability, and rollback evidence requirements."
    ],
    "exclusions": [
      "No change to Dataverse system-of-record ownership.",
      "No replacement of the model-driven operator entry surface.",
      "No direct client write to governed status.",
      "No second transition handler, workflow, webhook, queue consumer, or parallel close path.",
      "No unrelated schema, form, process, role, integration, AI, reporting, or backlog work.",
      "No tenant access, implementation, packaging, deployment, commit, or push under this brief."
    ]
  },
  "architecture": {
    "experience": [
      {
        "id": "EXP-001",
        "decision": "Use the existing model-driven case form and close command for resolution-reason entry, validation feedback, progress, and final outcome.",
        "rationale": "This preserves the settled operator journey and avoids a competing entry surface.",
        "evidence_status": "Confirmed"
      },
      {
        "id": "EXP-002",
        "decision": "Make feedback keyboard-accessible, screen-reader announced, focus-managed, and safe for narrow and long-content states.",
        "rationale": "The close workflow must remain usable across validation and asynchronous failure states.",
        "evidence_status": "Assumption"
      }
    ],
    "data": [
      {
        "id": "DAT-001",
        "decision": "Store the resolution reason on the existing Dataverse case record using one required text attribute whose exact schema details follow solution conventions.",
        "rationale": "The reason must be durable, operator-visible, and governed by the existing record lifecycle.",
        "evidence_status": "Assumption"
      },
      {
        "id": "DAT-002",
        "decision": "Persist the normalized reason and governed status transition atomically through the existing owner.",
        "rationale": "This prevents a closed case without a reason and prevents a reason from falsely implying successful closure.",
        "evidence_status": "Confirmed"
      }
    ],
    "integration": [
      {
        "id": "INT-001",
        "decision": "Extend only the existing form-to-handler close contract; add no new external integration or lifecycle consumer.",
        "rationale": "The slice needs no second processing path and must preserve one authoritative owner.",
        "evidence_status": "Confirmed"
      },
      {
        "id": "INT-002",
        "decision": "Carry a concurrency token and idempotency key or equivalent duplicate-action identifier through the existing close path.",
        "rationale": "This protects against stale overwrites, repeated clicks, retries, and replay.",
        "evidence_status": "Assumption"
      }
    ],
    "ai": [
      {
        "id": "AI-001",
        "decision": "Use no AI component in this slice.",
        "rationale": "Resolution entry, deterministic validation, persistence, and feedback do not require probabilistic behavior.",
        "evidence_status": "Confirmed"
      }
    ],
    "security": [
      {
        "id": "SEC-001",
        "decision": "Revalidate caller privileges and transition eligibility in the existing server-side handler.",
        "rationale": "Client visibility and client validation are not security boundaries.",
        "evidence_status": "Confirmed"
      },
      {
        "id": "SEC-002",
        "decision": "Continue rejecting direct client writes to governed status and exclude resolution content and identifiers from telemetry.",
        "rationale": "This preserves lifecycle integrity and minimizes sensitive operational data.",
        "evidence_status": "Confirmed"
      }
    ],
    "operations": [
      {
        "id": "OPS-001",
        "decision": "Use correlation-based, privacy-safe outcome telemetry with explicit success, validation, permission, conflict, duplicate, and transient-failure categories.",
        "rationale": "Operators and support staff need diagnosable outcomes without capturing the resolution text.",
        "evidence_status": "Assumption"
      },
      {
        "id": "OPS-002",
        "decision": "Treat duplicate or replayed close requests as one logical operation and expose a duplicate signal without repeating the transition.",
        "rationale": "Retries must be safe and operational evidence must distinguish replay from a new close.",
        "evidence_status": "Assumption"
      }
    ],
    "alm": [
      {
        "id": "ALM-001",
        "decision": "Package the attribute, form change, close-contract change, handler change, dependencies, and environment-bound telemetry configuration in the existing solution and deployment route.",
        "rationale": "The slice must be deployable and verifiable as one coherent increment.",
        "evidence_status": "Assumption"
      },
      {
        "id": "ALM-002",
        "decision": "Require package inspection, import evidence, configuration readback, runtime smoke evidence, and a tested rollback procedure before production promotion.",
        "rationale": "Local tests alone do not prove package integrity, target configuration, or runtime behavior.",
        "evidence_status": "Confirmed"
      }
    ]
  },
  "delegations": [],
  "acceptance_criteria": [
    {
      "id": "AC-001",
      "given": "An authorised operator has an eligible current case open in the model-driven app and enters a valid resolution reason.",
      "when": "The operator activates the existing close command.",
      "then": "The existing server-side handler atomically persists the normalized reason and performs exactly one close transition, after which the refreshed form shows the authoritative closed state and stored reason.",
      "evidence": "Focused handler test, package inspection, target Dataverse readback, and runtime success trace sharing one correlation ID."
    },
    {
      "id": "AC-002",
      "given": "The resolution reason is blank, whitespace-only, or longer than the configured limit.",
      "when": "The operator attempts closure.",
      "then": "Accessible validation identifies and focuses the reason field, no governed transition occurs, and no invalid reason is persisted.",
      "evidence": "Client validation test, server validation test, accessibility check, and target runtime negative-path readback."
    },
    {
      "id": "AC-003",
      "given": "The case changes after the operator loaded it.",
      "when": "The operator submits closure using the stale concurrency token.",
      "then": "The handler rejects the stale overwrite, preserves both the operator input and current Dataverse version, emits a conflict outcome, and tells the operator to reload and reconcile.",
      "evidence": "Concurrent-change automated test plus target runtime evidence showing no lost update."
    },
    {
      "id": "AC-004",
      "given": "The same close request is submitted or replayed more than once.",
      "when": "The handler receives the duplicate idempotency key or equivalent duplicate-action signal.",
      "then": "Only one reason write and one governed transition occur, and telemetry marks the duplicate or replay outcome.",
      "evidence": "Handler replay test and target telemetry correlated with a single resulting transition."
    },
    {
      "id": "AC-005",
      "given": "The caller lacks permission or the case is no longer eligible for closure.",
      "when": "A close request reaches the handler.",
      "then": "The handler rejects it without modifying reason or status, and the app shows actionable non-retry guidance without exposing restricted detail.",
      "evidence": "Security test, runtime negative-path readback, and sanitized feedback capture."
    },
    {
      "id": "AC-006",
      "given": "Any close attempt completes.",
      "when": "Operational telemetry is inspected.",
      "then": "A correlation ID, duration, outcome category, and conflict or duplicate signal are available, while the resolution reason and excluded payloads are absent.",
      "evidence": "Telemetry contract test, redaction test, and target telemetry query using synthetic records."
    }
  ],
  "negative_paths": [
    {
      "id": "NP-001",
      "condition": "Blank, whitespace-only, oversized, or malformed resolution reason.",
      "expected_behavior": "Reject before transition, preserve safe operator input, focus the field, and return a validation outcome.",
      "evidence": "Client and server boundary tests plus target negative-path readback."
    },
    {
      "id": "NP-002",
      "condition": "Unauthorized operator or insufficient field, record, or transition privilege.",
      "expected_behavior": "Reject server-side with no reason or status change and show sanitized permission feedback.",
      "evidence": "Impersonated security test and target role-based smoke test."
    },
    {
      "id": "NP-003",
      "condition": "Stale concurrency token or concurrent case modification.",
      "expected_behavior": "Reject without lost data, preserve the operator-entered reason locally, emit conflict telemetry, and require reload and reconciliation.",
      "evidence": "Concurrent-change test and before-and-after target record evidence."
    },
    {
      "id": "NP-004",
      "condition": "Repeated click, client retry, delayed response, or replayed close request.",
      "expected_behavior": "Suppress or deduplicate the request and never perform a second transition.",
      "evidence": "Duplicate-submission test, handler replay test, and correlated target trace."
    },
    {
      "id": "NP-005",
      "condition": "Transient server or network failure with an unknown client-visible outcome.",
      "expected_behavior": "Show retry-safe failure feedback, retain the reason, reuse or reconcile duplicate protection, and refresh authoritative state before declaring failure or success.",
      "evidence": "Injected failure test and runtime recovery trace."
    },
    {
      "id": "NP-006",
      "condition": "A client attempts to bypass the handler and write governed status directly.",
      "expected_behavior": "The write remains rejected and no partial resolution data is treated as a successful close.",
      "evidence": "Security regression test and target authorization evidence."
    }
  ],
  "tests": [
    {
      "id": "TEST-001",
      "class": "functional",
      "scope": "Valid reason submission, normalization, atomic persistence, one close transition, form refresh, and success feedback.",
      "expected": "The reason and closed state are committed together exactly once through the existing handler.",
      "evidence_required": "Focused automated results and synthetic target runtime record readback.",
      "status": "planned"
    },
    {
      "id": "TEST-002",
      "class": "functional",
      "scope": "Blank, whitespace-only, maximum-length, over-limit, and long-content behavior at client and server boundaries.",
      "expected": "Invalid input is rejected consistently and valid boundary input is preserved.",
      "evidence_required": "Form and handler test output.",
      "status": "planned"
    },
    {
      "id": "TEST-003",
      "class": "security",
      "scope": "Unauthorized closure, server-side privilege validation, telemetry redaction, and attempted direct governed-status writes.",
      "expected": "Unauthorized changes are rejected and sensitive payload content is absent from telemetry.",
      "evidence_required": "Security test output and target role/readback evidence.",
      "status": "planned"
    },
    {
      "id": "TEST-004",
      "class": "reliability",
      "scope": "Concurrent modification, stale submission, repeated click, replay, delayed response, transient failure, and safe retry.",
      "expected": "No lost update or duplicate transition occurs, and feedback reflects the authoritative outcome.",
      "evidence_required": "Concurrency and replay tests plus correlated runtime traces.",
      "status": "planned"
    },
    {
      "id": "TEST-005",
      "class": "accessibility",
      "scope": "Keyboard operation, focus movement, error association, busy and success announcements, disabled state, narrow layout, and long reason content.",
      "expected": "The complete close journey is operable and understandable without pointer or visual-only cues.",
      "evidence_required": "Automated accessibility results and manual keyboard and screen-reader checks.",
      "status": "planned"
    },
    {
      "id": "TEST-006",
      "class": "performance",
      "scope": "Close-handler duration and UI pending-state behavior under the existing representative synthetic workload.",
      "expected": "No material regression against the repository's existing close-path threshold, and the UI remains responsive while awaiting completion.",
      "evidence_required": "Comparative local measurement and target telemetry duration evidence.",
      "status": "planned"
    },
    {
      "id": "TEST-007",
      "class": "alm",
      "scope": "Solution component inclusion, dependencies, schema metadata, form placement, handler registration, and environment-variable binding.",
      "expected": "The exported package contains the complete slice with no unrelated component drift.",
      "evidence_required": "Package validation report and reviewed solution diff.",
      "status": "planned"
    },
    {
      "id": "TEST-008",
      "class": "deployment",
      "scope": "Target import, configuration readback, role verification, handler registration, and success and failure smoke paths.",
      "expected": "The target configuration matches the package and the synthetic runtime paths behave as specified.",
      "evidence_required": "Import log, configuration readback, role evidence, and correlated smoke traces.",
      "status": "not-run"
    },
    {
      "id": "TEST-009",
      "class": "rollback",
      "scope": "Revert form and handler activation while preserving any resolution reasons already committed by successful transactions.",
      "expected": "The prior close experience is restored without corrupting or silently deleting valid case history.",
      "evidence_required": "Non-production rollback rehearsal and post-rollback readback.",
      "status": "not-run"
    }
  ],
  "deployment": {
    "authorization_status": "not-requested",
    "target_zone": "organisational-microsoft",
    "environments": [
      "Authorised non-production Dataverse environment before any production promotion"
    ],
    "prerequisites": [
      "Inspect the current solution, form, close contract, handler, registration, security roles, test conventions, and duplicate-protection path.",
      "Resolve the publisher-prefixed attribute name, label, maximum length, form location, telemetry destination, and retention configuration.",
      "Confirm the target supports transactional persistence through the existing handler and identify its concurrency-token convention.",
      "Confirm authorised role access to the new attribute without broadening governed-status permissions.",
      "Back up or export the currently deployed solution version and record the handler configuration needed for rollback.",
      "Obtain explicit deployment authorization through the existing ALM process."
    ],
    "steps": [
      "Implement and validate the focused slice through the authorised build workflow.",
      "Export and inspect the solution artifact for intended components, dependencies, and unrelated drift.",
      "Import through the existing non-production ALM route.",
      "Bind telemetry configuration and verify handler registration and security roles.",
      "Run synthetic success, validation, permission, conflict, duplicate, transient-failure, retry, telemetry-redaction, and direct-write rejection checks.",
      "Promote only after evidence review and separate production authorization."
    ],
    "post_deploy_checks": [
      "Read back the resolution-reason attribute metadata and model-driven form placement.",
      "Read back the existing handler registration and confirm no second transition owner was introduced.",
      "Verify authorised operators can use the field and unauthorized users cannot bypass the handler.",
      "Verify valid closure persists the reason and governed status atomically.",
      "Verify stale and duplicate requests cause neither lost updates nor repeated transitions.",
      "Verify client feedback matches server outcomes and correlation IDs connect the two safely.",
      "Verify telemetry excludes reason text, record payloads, personal identifiers, tokens, and credentials.",
      "Verify direct client writes to governed status remain rejected."
    ],
    "evidence_required": [
      "Reviewed source and solution diff.",
      "Focused automated test results.",
      "Package dependency and component-integrity report.",
      "Target import log and configuration readback.",
      "Security-role and handler-registration readback.",
      "Synthetic runtime success, failure, conflict, replay, and retry traces.",
      "Telemetry correlation and redaction evidence.",
      "Recorded evidence level distinguishing local, package, deployment, and target-runtime proof."
    ]
  },
  "rollback": {
    "triggers": [
      "Reason or status can be committed without the other.",
      "Unauthorized closure or direct governed-status write becomes possible.",
      "Valid existing close journeys regress.",
      "Stale or duplicate requests cause lost updates or repeated transitions.",
      "Telemetry exposes resolution text or another excluded payload.",
      "Target failures exceed the agreed operational threshold after deployment."
    ],
    "steps": [
      "Disable or revert the new form and close-contract activation using the existing ALM rollback route.",
      "Restore the previously exported solution and handler configuration.",
      "Confirm the original server-side transition owner is active and no competing owner remains.",
      "Retain successfully committed resolution reasons unless an approved data-remediation decision requires otherwise.",
      "Run the prior close regression path and direct-write rejection check.",
      "Record affected correlation IDs and reconcile ambiguous in-flight attempts against authoritative Dataverse state."
    ],
    "data_considerations": [
      "Do not bulk-delete or blank successfully persisted resolution reasons during technical rollback.",
      "Identify partial or ambiguous operations by correlation ID and reconcile them individually against Dataverse.",
      "Do not replay a close request without duplicate protection and current-state validation.",
      "Apply organisational retention and audit requirements to resolution data and rollback evidence."
    ],
    "owner": "Authorised solution and operational owners for the existing case-management solution",
    "evidence_required": [
      "Pre-change solution export and handler configuration record.",
      "Non-production rollback rehearsal result.",
      "Post-rollback handler, role, form, and record-state readback.",
      "Regression and direct-write rejection test results.",
      "Reconciliation record for any ambiguous in-flight operations."
    ]
  },
  "next_action": "Hand this Ready brief to the authorised implementation workflow: inspect the existing close contract and handler, resolve the bounded schema and telemetry configuration values, implement only this slice, run the planned focused tests, inspect the solution artifact, and seek separate deployment authorization. Carry forward that local form and handler tests were previously proved, while package, target configuration, security, telemetry, concurrency, replay, failure-recovery, rollback, and runtime end-to-end evidence remain unproved."
}
